from collections import defaultdict

def topological_sort(graph: dict[str, list[str]]) -> tuple[list[str], list[str] | None]:
    """
    Returns a topological order of dependency keys from the given graph.

    Parameters:
    graph (dict): A dictionary representing an undirected graph where each key is a node and its value is a list of nodes it depends on.

    Returns:
    tuple: A sorted list of nodes in topological order, or None if there's a cycle.
    """
    def dfs(node):
        if not visited[node]:
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    dfs(neighbor)
            result.append(node)

    def detect_cycle():
        visited = defaultdict(bool)
        on_stack = defaultdict(bool)
        stack = []

        for node in graph:
            if not visited[node]:
                dfs(node)
                cycle_nodes.append(result.pop())
                while len(stack) > 0 and stack[-1] == cycle_nodes[0]:
                    result.pop()
                    stack.pop()
                    cycle_nodes.pop()

    def build_graph():
        nonlocal result
        for node in graph:
            if not visited[node]:
                dfs(node)
                result = []
                detect_cycle()
                return

    # Initialize variables and start building the graph
    result = []
    visited = defaultdict(bool)
    build_graph()

    if len(result) != len(graph):
        cycle_nodes = [node for node in graph if node not in result]
        return ([], cycle_nodes)

    return tuple(result)

# Example usage:
graph1 = {
    'A': ['B', 'C'],
    'B': ['D'],
    'C': ['E'],
    'D': [],
    'E': []
}

graph2 = {
    'A': ['B', 'C'],
    'B': ['D'],
    'C': ['E'],
    'D': ['F'],
    'E': ['F']
}

print(topological_sort(graph1))  # Expected: (['A', 'B', 'C', 'D', 'E', 'F'], None)
print(topological_sort(graph2))  # Expected: ([], ['A', 'B', 'C', 'D', 'E', 'F'])
